#!/usr/bin/env bash
# Generated by kubegen from examples/dks.yaml - re-generate instead of editing.
# Creates the dks cluster "staging-do".
set -euo pipefail

die() { echo "error: $*" >&2; exit 1; }

# Required tools
missing=0
need() {
  command -v "$1" >/dev/null 2>&1 && return
  echo "error: required tool '$1' is not installed or not in PATH" >&2
  echo "       install it from: $2" >&2
  missing=1
}
need doctl https://docs.digitalocean.com/reference/doctl/how-to/install/
need kubectl https://kubernetes.io/docs/tasks/tools/
[ "$missing" -eq 0 ] || exit 127

echo '==> Checking DigitalOcean credentials'
doctl account get >/dev/null 2>&1 || die "doctl is not authenticated; run: doctl auth init"

echo '==> Creating DigitalOcean Kubernetes cluster staging-do (this takes several minutes)'
doctl kubernetes cluster create staging-do \
  --region nyc3 --version latest \
  --node-pool 'name=default;size=s-4vcpu-8gb;count=3' \
  --node-pool 'name=jobs;size=c-4;count=1;auto-scale=true;min-nodes=1;max-nodes=5;label=workload=jobs;taint=workload=jobs:NoSchedule' \
  --ha \
  --auto-upgrade \
  --surge-upgrade \
  --maintenance-window saturday=02:00 \
  --tag env:staging \
  --wait

echo '==> Verifying access to staging-do'
kubectl get nodes -o wide

echo "Cluster staging-do is ready."
